  "supportive_card_ids": ["C170","C125","C135","C129","C157","C145","C97","C108","C86","C81","C87","C185","C194","C212","C191","C192","C223"],
  "contradictory_card_ids": ["C190","C199","C211","C210","C224"],
  "prediction_basis_card_ids": ["C170","C135","C97","C108","C185"],
  "claims": [
    {
      "claim": "The query is glipizide, a sulfonylurea sharing the N-cyclohexylsulfonylurea and phenethyl linker with glyburide (L3/L4 M02, L5 M01) and gliquidone (L5 M02); glyburide is the closest transferable experimental reference.",
      "card_ids": ["C170","C190"]
    },
    {
      "claim": "Glyburide shows high Caco-2 absorptive permeability (Papp 18.1 ± 0.8 ×10^-6 cm/s; 24.9 ± 5.7 ×10^-6 cm/s with Pgp inhibition) and high passive permeability (19.0 ± 2.6 ×10^-6 cm/s), supporting efficient intestinal absorption for this chemotype despite ionization.",
      "card_ids": ["C170","C125","C211"]
    },
    {
      "claim": "Glyburide solubility in fasted human intestinal fluid is 5–66 µg/mL (thermodynamic 9.2–15.4 µg/mL), and glyburide formulations show complete release in FaSSIF, indicating luminal dissolution is not an inherent barrier.",
      "card_ids": ["C135","C129","C157","C145"]
    },
    {
      "claim": "L3 oral-exposure records for sulfonylureas show substantial systemic AUC/Cmax after oral dosing (glyburide AUCss 525.7 ng·h/mL; glimepiride AUC0-∞ 1215 ng·h/mL; gliclazide AUC0-∞ 56.32 µg·h/mL; tolbutamide AUC0-1.5hr 22.1 µg·h/mL), consistent with F≥20%.",
      "card_ids": ["C97","C108","C81","C87"]
    },
    {
      "claim": "L5 shows glyburide is a Pgp/BCRP/OATP2B1 substrate with efflux ratios 2.65–4, but in vivo jejunal efflux after IV is only 0.02–0.03% of dose in 60 min (C185), and high passive permeability offsets efflux; MRP1/3 are not involved in gliquidone (C212/C191). Thus gut-wall efflux is not threshold-relevant for this sulfonylurea class.",
      "card_ids": ["C190","C199","C211","C185","C212","C191"]
    },
    {
      "claim": "No direct absolute F measurement for glipizide or a close sulfonylurea is supplied; the high prediction rests on transferable permeability, solubility, oral-exposure, and efflux evidence, so confidence remains moderate.",
      "card_ids": ["C170","C135","C97","C185"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C185","C194","C212","C191","C188","C192","C223","C190","C199","C211","C210","C224"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for glipizide or any sulfonylurea is supplied; F is inferred from permeability, solubility, oral exposure, and efflux mechanism.",
    "No matched oral-versus-IV comparison for glipizide or a close sulfonylurea analog is supplied.",
    "No glipizide-specific Caco-2, solubility, dissolution, or transporter data are supplied; transfer from glyburide/gliquidone is based on the shared N-cyclohexylsulfonylurea core, but the benzamide/pyrazinecarboxamide difference could alter transporter affinity and metabolism.",
    "L5 contains no direct intestinal metabolism data for sulfonylureas; gut-wall first-pass metabolism remains unquantified.",
    "Condition match is imperfect: the query has no reported external condition, while some training contexts are fed/fasted/cirrhosis; L3-L5 records are mostly healthy/fasted/fed and may not capture disease effects.",
    "No ChEMBL evidence was provided; the physicochemical prior is uncertain and not used as endpoint proof."
  ],
  "decision_summary": "Predicted high because the query is a glipizide-like sulfonylurea; L4 shows high Caco-2 permeability and adequate intestinal-fluid solubility/dissolution for glyburide, L3 shows substantial oral exposure for the sulfonylurea class, and L5 shows that Pgp/BCRP efflux is modest and in vivo jejunal secretion is small, so gut-wall efflux does not affirm F<20%. Confidence remains moderate because no direct F measurement for glipizide is supplied."
}

